\begin{lemma}
\label{lemma-every-point-residual-gerbe-locally-Noetherian}
Let $\mathcal{X}$ be a locally Noetherian algebraic stack.
Then the residual gerbe of $\mathcal{X}$ at $x$ exists for
every $x \in |\mathcal{X}|$.
\end{lemma}

